function drawHull(p1, p2, p3, p4) {
  beginShape();
  vertex(p1.x, p1.y);
  vertex(p2.x, p2.y);
  vertex(p3.x, p3.y);
  vertex(p4.x, p4.y);
  endShape(CLOSE);
}

function drawPoints(p1, p2, p3, p4) {
  for (x = 0; x <= N; x++) {
    const x1 = lerp(p1.x, p2.x, x / N);
    const y1 = lerp(p1.y, p2.y, x / N);
    // point(x1, y1);
    const x2 = lerp(p4.x, p3.x, x / N);
    const y2 = lerp(p4.y, p3.y, x / N);
    // point(x2, y2);

    for (y = 0; y <= N; y++) {
      const xx = lerp(x1, x2, y / N);
      const yy = lerp(y1, y2, y / N);
      point(xx, yy);
    }
  }
}

function mousePressed() {
  if (mouseButton === LEFT) setup();
